// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Kişisel finans hesapları: faiz, bütçe, kredi (zor).
const ozEconomics12Zor = <(String, String, List<String>, String)>[
  ('Bir banka aylık yüzde 1 faizi her ay anaparaya ekleyerek işletiyor. 1.000 lira bir yıl sonunda yaklaşık kaç lira olur?', '1.126,83 lira', ['1.120,00 lira', '1.116,17 lira', '11.254,40 lira'], '1.000 × 1,01¹² ≈ 1.126,83 liradır. Basit toplamayla bulunan 1.120 lira bileşik etkiyi yok sayar.'),
  ('Yıllık yüzde 20 bileşik faizle yatırılan bir paranın üç katına çıkması için en az kaç tam yıl gerekir?', '7 yıl', ['5 yıl', '6 yıl', '10 yıl'], '1,2⁶ ≈ 2,99 olduğundan 6 yılda para üç katına ulaşmaz. 1,2⁷ ≈ 3,58 olduğundan 7. yılın sonunda üç katını geçer.'),
  ('Kredi kartı borcuna aylık yüzde 4 faiz işleyen ve hiç ödeme yapmayan bir kişinin borcu bir yılda yaklaşık kaç katına çıkar?', '1,6 katına', ['1,48 katına', '2,00 katına', '2,40 katına'], '1,04¹² ≈ 1,601 olduğundan borç yaklaşık 1,6 katına çıkar. Basit toplamla bulunan 1,48 katı bileşik etkiyi yok sayar.'),
  ('Bir arkadaşına 4.000 lira borç veren Murat, 8 ay sonra 4.400 lirasını geri alıyor. Bu işlemin yıllık basit faiz oranı yaklaşık yüzde kaçtır?', '15', ['10,5', '12', '18'], 'Faiz 400 liradır. Oran = 400 ÷ (4.000 × 8/12) = 0,15 yani yüzde 15\'tir.'),
  ('İki yıl sonra 14.000 lira geri ödenmek üzere alınan bir borçta yıllık yüzde 20 basit faiz uygulanıyorsa borcun başlangıç tutarı kaç liradır?', '10.000 lira', ['11.200 lira', '11.666,67 lira', '12.000 lira'], 'Anapara × (1 + 0,20 × 2) = 14.000 olduğundan anapara 14.000 ÷ 1,4 = 10.000 liradır.'),
  ('Ali yıllık yüzde 12 basit faizle 5 yıl, Veli aynı anaparayı yıllık yüzde 12 bileşik faizle aynı süre yatırdı. Faiz gelirleri kıyaslandığında hangisi doğrudur?', 'Veli\'nin faizi yaklaşık yüzde 76, Ali\'ninki yüzde 60', ['Her ikisinin faizi anaparanın yüzde 60\'ıdır', 'Ali\'nin faizi anaparanın yüzde 76\'sıdır, Veli\'ninki yüzde 60\'ıdır', 'Veli\'nin faizi anaparanın yaklaşık yüzde 70\'idir, Ali\'ninki yüzde 50\'dir'], 'Ali\'nin faizi 0,12 × 5 = yüzde 60\'tır. Veli\'nin faizi 1,12⁵ − 1 ≈ yüzde 76,2\'dir.'),
  ('Her ay sonunda 1.000 lira yatırılan ve aylık yüzde 1 bileşik faiz veren bir hesapta 24. ayın sonunda yaklaşık ne kadar para birikir?', '26.973 lira', ['240.000 lira', '27.273 lira', '25.432 lira'], 'Düzenli ödemelerin gelecek değeri 1.000 × [(1,01²⁴ − 1) ÷ 0,01] ≈ 26.973 liradır. Toplam yatırılan 24.000 liranın üzerindeki kısım faizdir.'),
  ('Bir ödeme planında her yıl sonunda 3.000 lira olmak üzere 4 yıl boyunca ödeme alınacaktır. Yıllık iskonto oranı yüzde 5 ise bu ödemelerin bugünkü toplam değeri yaklaşık kaç liradır?', '10.638 lira', ['10.000 lira', '11.250 lira', '12.000,00 lira'], 'Anüite bugünkü değeri 3.000 × [(1 − 1,05⁻⁴) ÷ 0,05] ≈ 10.638 liradır. Toplam nominal 12.000 liranın altındadır çünkü ileri tarihli paralar iskonto edilir.'),
  ('Elif 5 yıl sonra 100.000 lira biriktirmek istiyor ve yıllık yüzde 10 bileşik getiri bekliyor. Bugün tek seferlik yatıracağı tutar yaklaşık kaç lira olmalıdır?', '62.092 lira', ['50.000 lira', '66.667 lira', '90.909,09 lira'], '100.000 ÷ 1,1⁵ ≈ 62.092 liradır. 50.000 lira yıllık yüzde 10 basit toplamla bulunmuş hatalı bir değerdir.'),
  ('120.000 lira, aylık yüzde 2 faizle 12 ay vadeli ve eşit anapara ödemeli olarak çekilmiştir. İlk taksit kaç liradır?', '12.400 lira', ['10.200 lira', '10.000 lira', '11.347,15 lira'], 'Aylık anapara 120.000 ÷ 12 = 10.000 lira, ilk ay faizi 120.000 × 0,02 = 2.400 liradır. İlk taksit 12.400 liradır.'),
  ('60.000 liralık kredi 6 ayda, aylık yüzde 3 faizle eşit anapara ödemeli geri ödenecektir. Toplam ödenecek faiz kaç liradır?', '6.300 lira', ['3.600 lira', '6.455 lira', '10.800 lira'], 'Faizler 1.800, 1.500, 1.200, 900, 600 ve 300 liradır; toplamları 6.300\'dür. Bu tutar, eşit taksitli plana göre hesaplanan yaklaşık 6.455 liradan düşüktür.'),
  ('100.000 lira kredi çeken biri dosya masrafı olarak 1.500 lira ve zorunlu sigorta olarak 3.500 lira ödüyor, eline 95.000 lira geçiyor. Bu durumda kredinin gerçek maliyetine nasıl yansır?', 'Etkin maliyet artar; fiilen 95.000 lira kullanılır', ['Etkin maliyet düşer, çünkü masraflar faizden mahsup edilir', 'Etkin maliyet değişmez, çünkü masraf faizle ilgisizdir', 'Masraflar vergiden düşüldüğü için kredi bedava olur'], 'Borçlu 100.000 lira üzerinden faiz öderken fiilen 95.000 lira kullanır; bu yüzden etkin yıllık maliyet nominal orandan yüksek olur.'),
  ('Bir kişinin bir ayda net geliri 45.000 lira, zorunlu giderleri 27.000 lira, isteğe bağlı harcamaları 12.000 liradır. Aylık serbest nakit akışı ve bunun gelire oranı hangisidir?', '6.000 lira; yüzde 13,3', ['18.000 lira; yüzde 40', '6.000 lira; yüzde 20', '33.000 lira; yüzde 73,3'], 'Serbest nakit = 45.000 − 27.000 − 12.000 = 6.000 liradır. Oranı 6.000 ÷ 45.000 ≈ yüzde 13,3\'tür.'),
  ('Bir freelance çalışanın yılda 12 ay boyunca aylık gelirleri sırasıyla 20, 50, 10, 40, 30, 20, 60, 10, 30, 40, 20 ve 30 bin liradır. Giderleri her ay 28 bin lira ise bu kişi için aylık bütçe planlamasında hangisi daha uygundur?', 'Fazla aylarda fon biriktirmek', ['Her ay gelirini tamamen harcamak', 'Gelir yüksek aylarda ek kredi çekmek', 'Düşük gelirli aylarda gideri sıfırlamak'], 'Ortalama gelir (360 ÷ 12 = 30 bin lira) giderleri aştığı için yüksek gelirli aylardan ayrılan fon, düşük aylardaki açığı kapatır.'),
  ('Bir ailenin net değeri, yıl başında 600.000 lira iken yıl sonunda 690.000 lira olmuştur. Aynı sürede enflasyon yüzde 20 ise ailenin servetindeki gerçek (reel) değişim hakkında hangisi doğrudur?', 'Nominal yüzde 15 artmış, reel olarak azalmıştır', ['Nominal ve reel olarak yüzde 15 artmıştır', 'Nominal olarak azalmış ama reel olarak artmıştır', 'Enflasyondan etkilenmediği için aynıdır'], '690.000 ÷ 600.000 = 1,15 (yüzde 15 nominal artış). Fiyatlar yüzde 20 arttığından alım gücü yaklaşık yüzde 4 azalmıştır.'),
  ('Yıllık kart ücreti 600 lira olan kartla yıl içinde toplam 40.000 lira harcama yapan ve harcamaların yüzde 1,5\'i kadar puan kazanan biri için puan geliri aidatı karşılar mı?', 'Evet; 600 lira puan aidata eşittir', ['Evet; 1.200 lira puan kazanır ve 600 lira kâr kalır', 'Hayır; hiç puan kazanamaz', 'Hayır; 6.000 lira puan kazanır ve zarar eder'], '40.000 × 0,015 = 600 liradır. Puan geliri aidata eşit olduğu için kullanıcı baştan başa gider; avantaj ancak daha fazla harcamayla doğar.'),
  ('Tüketici hukukunda teslimden sonraki ilk altı ay içinde ortaya çıkan bir ayıp için ispat yükü nasıl düzenlenmiştir?', 'Ayıbın teslimde olmadığını satıcı ispatlar', ['Ayıbın teslim anında var olduğunu tüketici ispatlamak zorundadır', 'İki taraf da ispat yükünden muaftır', 'Yalnızca üretici firma ispatlamak zorundadır'], 'Altı ay içinde ortaya çıkan ayıpların teslim anında mevcut olduğu varsayılır; aksini kanıtlama yükü satıcıdadır.'),
  ('Aynı ürünü 3.000 liraya nakit, 3.600 liraya 6 taksitle sunan bir satıcının nakit ödemede "indirim", taksitte "fark" ifadesi kullanması hangi etkiyi hedefler?', 'Çerçeveleme etkisi', ['Çıpalama ile fiyatı sıfıra indirmek', 'Arz fazlası yaratmak', 'Vergi borcunu azaltmak'], 'Aynı fark "taksit faizi" olarak da "nakit indirimi" olarak da anlatılabilir; sunuş biçimi tercihi etkiler.'),
  ('Prelec ve Simester\'in deneyinde basketbol bileti için kredi kartı ile ödeyeceğini söyleyen katılımcıların ödemeye razı olduğu fiyat, nakit ödeyenlere göre nasıl çıkmıştır?', 'Daha yüksek', ['Önemli ölçüde daha düşük', 'Tamamen aynı', 'Hiç belirlenememiş'], 'Kartla ödemede "ödemenin acısı" daha az hissedildiği için katılımcılar daha yüksek fiyat vermeye istekli olmuştur.'),
  ('Bir tüketici üç paket arasında seçim yapıyor: küçük 50, orta 75, büyük 80 lira. Orta boyun neredeyse büyük kadar pahalı olması büyük boyun tercih edilmesine nasıl yol açar?', 'Orta boy yem görevi görür', ['Orta boy en ucuz seçenek olduğu için seçilir', 'Küçük boy fiyatı sıfıra düşürür', 'Büyük boy her zaman gereksiz görülür'], 'Yem (tuzak) seçenek, diğer seçeneklerin göreli çekiciliğini değiştirir; orta ile büyük arasındaki küçük fark büyüğü çekici kılar.'),
  ('Aynı varsayımsal tarifeyle 180.000 liralık matrah için ortalama vergi oranı yaklaşık yüzde kaçtır ve marjinal vergi oranı kaçtır?', 'Ortalama 17,2; marjinal 20', ['Ortalama yüzde 20; marjinal yüzde 17,2', 'Ortalama yüzde 15; marjinal yüzde 15', 'Ortalama yüzde 27; marjinal yüzde 20'], 'Ortalama oran 31.000 ÷ 180.000 ≈ yüzde 17,2\'dir. Son lira yüzde 20 dilimine düştüğü için marjinal oran yüzde 20\'dir.'),
  ('Aynı tarifede matrahı 240.000 liradan 260.000 liraya çıkan bir kişinin ek 20.000 lirası ne kadar vergilendirilir?', '4.700 lira', ['4.000 lira', '5.400,50 lira', '3.000 lira'], '250.000 liraya kadar olan 10.000 lira yüzde 20\'den 2.000, aşan 10.000 lira yüzde 27\'den 2.700 lira vergilenir; toplam 4.700 liradır.'),
  ('Brüt maaşı 50.000 lira olan bir çalışanda şu varsayımsal kesintiler uygulanıyor: SGK işçi payı yüzde 14 ve işsizlik primi yüzde 1 (brüt üzerinden), gelir vergisi yüzde 15 (SGK düşüldükten sonraki matrah üzerinden), damga vergisi binde 7,59 (brüt üzerinden). Net maaş yaklaşık kaç liradır?', '35.746 lira', ['37.500 lira', '41.250 lira', '29.500,50 lira'], 'SGK ve işsizlik 7.500, gelir vergisi 42.500 × 0,15 = 6.375, damga vergisi 379,5 liradır. Net maaş 50.000 − 14.254,5 ≈ 35.746 liradır.'),
  ('Çalışanın bir yıl önce brüt maaşı 40.000, bugünkü brüt maaşı 48.000 lira oldu. Aynı sürede yıllık enflasyon yüzde 30 ise brüt maaşın reel değişimi için ne söylenebilir?', 'Nominal yüzde 20 artmış, reel yüzde 7,7 azalmıştır', ['Nominal ve reel yüzde 20 artmıştır', 'Nominal yüzde 20 artmış, reel olarak değişmemiştir', 'Nominal yüzde 30 artmış, reel olarak yüzde 10 artmıştır'], '1,20 ÷ 1,30 ≈ 0,923 olduğundan satın alma gücü yaklaşık yüzde 7,7 düşmüştür.'),
  ('Bir evin bir yıl içinde 400.000 liralık tam hasara uğrama olasılığı binde 5 ise sigortacının bu risk için hesaplayacağı beklenen hasar (saf prim) kaç liradır?', '2.000 lira', ['5.000 lira', '20.000 lira', '200 lira'], 'Beklenen hasar = olasılık × hasar tutarı = 0,005 × 400.000 = 2.000 liradır. Gerçek prim bunun üzerine gider ve kâr payı eklenir.'),
  ('Bir konutun satış fiyatı 3.000.000 lira, aylık kirası 15.000 liradır. Fiyatın yıllık kiraya oranı (fiyat/kira çarpanı) yaklaşık kaçtır?', '16,7', ['12,5', '20,0', '8,333'], 'Yıllık kira 15.000 × 12 = 180.000 liradır; 3.000.000 ÷ 180.000 ≈ 16,7. Oran yükseldikçe satın almak kiralamaya göre pahalılaşır.'),
  ('Aylık kirası bugün 20.000 lira olan bir evin kirasına her yıl yüzde 40 zam yapılırsa iki yıl sonraki aylık kira kaç liradır?', '39.200 lira', ['36.000,00 lira', '28.000 lira', '40.000 lira'], '20.000 × 1,4 × 1,4 = 39.200 liradır. Zamlar birbirinin üstüne bindiği için iki yıllık artış yüzde 96\'dır, yüzde 80 değil.'),
  ('Üç ay boyunca her ay 1.000 lira ile aynı fona yatırım yapan bir kişi, ay başlarında birim fiyatı 10, 5 ve 20 liradır. Alınan toplam pay sayısı ve ortalama maliyet nedir?', '350 pay; ortalama maliyet yaklaşık 8,57 lira', ['350 pay; ortalama maliyet yaklaşık 11,67 lira', '300 pay; ortalama maliyet 10 lira', '200 pay; ortalama maliyet 11,67 lira'], '1.000 lira ile 100, 200 ve 50 pay alınır; toplam 350 pay ve 3.000 ÷ 350 ≈ 8,57 liradır. Düzenli yatırım, ortalama maliyeti fiyat ortalamasının altında tutar.'),
  ('100.000 liralık varlığın yıllık yüzde 25 enflasyonda üç yıl sonra, aynı mal sepetini alabilme gücü yaklaşık kaç liradır (varlık getirisiz kabul edilir)?', '51.200 lira', ['25.000 lira', '75.000 lira', '56.250,00 lira'], 'Fiyatlar 1,25³ ≈ 1,953 katına çıkar; alım gücü 100.000 ÷ 1,953 ≈ 51.200 liraya iner. Yüzde 75 kayıp varsayımı hatalıdır.'),
  ('Sendika üyesi bir çalışan toplu sözleşmede yıllık yüzde 30 zam alırken beklenen enflasyon yüzde 40 ise reel ücret kazanımı için ne söylenebilir?', 'Reel ücret yaklaşık yüzde 7 azalır', ['Beklenen reel ücret yaklaşık yüzde 10 artar', 'Reel ücret sabit kalır', 'Reel ücret yüzde 30 artar'], '1,30 ÷ 1,40 ≈ 0,929 olduğundan satın alma gücü yaklaşık yüzde 7 düşer.'),
  ('Bir ürün önce yüzde 25 zamlanıp sonra "yüzde 20 indirim" ilanıyla satılırsa son fiyatın ilk fiyata oranı nedir?', 'Aynıdır', ['Yüzde 5 daha ucuzdur', 'Yüzde 5 daha pahalıdır', 'Yüzde 20 daha ucuzdur'], '1,25 × 0,80 = 1 olduğundan ürün başlangıç fiyatına döner; indirim yalnızca şişirilmiş fiyata uygulanmıştır.'),
  ('Toptan alınan 12 kilogramlık bir ürünün kilosu 50 liradır ve bozulma yüzünden yüzde 30\'u çöpe gitmektedir. Kullanılabilir ürünün gerçek kilo maliyeti yaklaşık kaç liradır?', '71,4 lira', ['50,0 lira', '65,0 lira', '180,0 lira'], 'Toplam bedel 600 liradır, kullanılabilir miktar 8,4 kg\'dır. 600 ÷ 8,4 ≈ 71,4 lira/kg çıkar; toptan alım ucuz görünse de zayiat maliyeti artırır.'),
  ('Peşin fiyatı 10.000 lira olan ürün, 12 ay boyunca her ay sonunda 1.000 lira taksitle toplam 12.000 liraya satılıyor. Taksitli satıştaki örtük aylık faiz yaklaşık yüzde kaçtır?', '2,9', ['1,0', '1,7', '14,2'], '10.000 = 1.000 × [(1 − (1 + r)⁻¹²) ÷ r] denkleminin çözümü r ≈ yüzde 2,92\'dir. Bu da yıllık efektif yaklaşık yüzde 41\'e denk gelir.'),
  ('Peşin fiyatı 3.000 lira olan bir cihaz, 6 ay boyunca ay sonlarında 600 lirayla taksitli satılıyor. Örtük aylık faiz hakkında aşağıdakilerden hangisi doğrudur?', 'Aylık yaklaşık yüzde 5,5; faizsiz yanıltıcıdır', ['Aylık yüzde 0; çünkü fiyat bellidir', 'Aylık yaklaşık yüzde 1; çünkü fark küçüktür', 'Aylık yaklaşık yüzde 20; çünkü fark 600 liradır'], 'Toplam 3.600 liradır, 3.000 lirayı 6 eşit ödemeyle ödemek için gereken faiz yaklaşık yüzde 5,5\'tir. Peşin fiyat farkı örtük faizdir.'),
  ('Peşin fiyatı 4.000 lira olan buzdolabı 4 taksit için 4.200 lira (ayda 1.050 lira) olarak satılıyor. Tüketici, parasını yıllık yüzde 40 basit faizle değerlendirebiliyorsa hangi seçenek daha uygundur?', 'Taksit; örtük faiz piyasa getirisinden düşük', ['Peşin; çünkü taksit ayda yüzde 10 pahalıdır', 'Peşin; çünkü taksit yıllık yüzde 100 faizlidir', 'İkisi de aynıdır çünkü fark sabittir'], 'Ödemeler aylık 1.050 liradır; aylık örtük faiz yaklaşık yüzde 2 (yıllık basit yaklaşık yüzde 24) çıkar. Bu oran yüzde 40\'ın altında olduğu için taksit uygundur.'),
  ('Yıllık 600 lira, aylık 70 lira olan bir dijital abonelikte yıllık paketin aylığa göre kaç ay kullanımda kârlı hale geldiği hangisidir?', '9. ayın başında kârlı olur', ['5. ayın başında kârlı olur', '12. ayın sonunda kârlı olur', 'Hiçbir zaman kârlı olmaz'], '600 ÷ 70 ≈ 8,57 olduğundan 9 ay ya da daha uzun kullanılacaksa yıllık paket ucuzdur.'),
  ('Beş yıl sonra bugünkü fiyatı 600.000 lira olan bir araç için peşinat biriktiren kişi, yıllık enflasyon yüzde 20 ise hedefini kaç liraya göre planlamalıdır?', 'Yaklaşık 1.493.000 lira', ['600.000 lira', '1.200.000 lira', '1.000.000 lira'], '600.000 × 1,20⁵ ≈ 1.492.992 liradır. Hedef tutarı bugünkü fiyatla planlamak yetersiz kalır.'),
  ('24 ay sonra 120.000 lira biriktirmek isteyen kişi, hesabı aylık yüzde 1,5 bileşik getiri sağlıyorsa ay sonlarında yaklaşık ne kadar yatırmalıdır?', 'Yaklaşık 4.191 lira', ['5.000 lira', '3.000 lira', '6.250 lira'], 'Gelecek değer formülünden yatırım = 120.000 × 0,015 ÷ (1,015²⁴ − 1) ≈ 4.191 liradır; faiz sayesinde 5.000 liradan az ayırmak yeterlidir.'),
  ('Bir tüketici 10.000 liralık nakit kredi için aylık yüzde 3 faiz ödüyor. Aynı koşulda borcunu hiç ödemeden iki ay bekletirse (aylık bileşik) borç kaç liraya çıkar?', '10.609 lira', ['10.600,00 lira', '10.300 lira', '11.000 lira'], '10.000 × 1,03² = 10.609 liradır; basit toplamayla bulunan 10.600 liralık sonuç ikinci ayın faizinin faiz getirisini hesaba katmaz.'),
  ('Bir satış temsilcisi, sabit 30.000 lira maaş ya da yüzde 50 olasılıkla 70.000, yüzde 50 olasılıkla 10.000 lira kazandıracak komisyonlu seçenek arasında kalıyor. Komisyonlu seçeneğin beklenen kazancı nedir?', '40.000 lira', ['30.000 lira', '70.000,00 lira', '10.000 lira'], '0,5 × 70.000 + 0,5 × 10.000 = 40.000 liradır. Beklenen değer yüksek olsa da gelir dalgalıdır; risk tercihine göre karar değişebilir.'),
  ('Bir yatırım bir yıl yüzde 50 kazandırıp ertesi yıl yüzde 50 kaybettiriyorsa 10.000 lira ile başlayan kişi iki yıl sonunda kaç liraya sahip olur?', '7.500 lira', ['10.000 lira', '12.500 lira', '5.000 lira'], '10.000 × 1,5 × 0,5 = 7.500 liradır. Yüzde 50 artış ve azalış birbirini götürmez; dalgalanma bileşik getiriyi düşürür.'),
  ('Üç yıl boyunca yıllık getirileri sırasıyla yüzde 20, yüzde −10 ve yüzde 30 olan bir yatırımın aritmetik ortalaması ile bileşik (geometrik) ortalaması için hangisi doğrudur?', 'Aritmetik ortalama 13,3; bileşik yaklaşık 12,0 ve daha düşük', ['Aritmetik ortalama yüzde 13,3; bileşik yıllık getiri yaklaşık yüzde 14,5', 'İkisi de yüzde 13,3\'tür', 'Aritmetik ortalama yüzde 40; bileşik getiri yüzde 13,3\'tür'], 'Aritmetik ortalama 40 ÷ 3 ≈ 13,3\'tür. Bileşik getiri (1,2 × 0,9 × 1,3)^(1/3) − 1 ≈ yüzde 12,0\'dir; dalgalı getirilerde geometrik ortalama daha küçüktür.'),
  ('100.000 lira beş yılda 180.000 liraya çıkıyorsa yıllık bileşik büyüme oranı yaklaşık yüzde kaçtır?', '12,5', ['8,0', '16,67', '18,0'], '(1,8)^(1/5) − 1 ≈ 0,1247 olduğundan yaklaşık yüzde 12,5\'tir. Basit ortalama 80 ÷ 5 = yüzde 16\'dır ve yanıltıcıdır.'),
  ('Paranın üç katına çıkması için gereken yılı yaklaşık veren "114 kuralına" göre yıllık yüzde 6 getiriyle bu süre kaç yıldır?', 'Yaklaşık 19 yıl', ['Yaklaşık 12 yıl', 'Yaklaşık 38 yıl sonra', 'Yaklaşık 6 yıl'], '114 ÷ 6 = 19 yıldır; ln 3 ÷ ln 1,06 ≈ 18,9 ile uyumludur. 72 kuralı ikiye katlanma, 114 kuralı üçe katlanma içindir.'),
  ('Brüt yüzde 50 faiz getirisi olan, yüzde 15 stopaj kesilen bir hesapta yıllık enflasyon yüzde 40 ise yaklaşık reel net getiri nedir?', 'Yaklaşık yüzde +1,8', ['Yaklaşık yüzde +10,0', 'Yaklaşık yüzde −1,8', 'Yaklaşık yüzde +2,5'], 'Net nominal getiri 50 × 0,85 = yüzde 42,5\'tir. Tam reel getiri (1,425 ÷ 1,40) − 1 ≈ yüzde 1,8\'dir; yüzde 2,5 yalnızca basit çıkarmayla bulunan yaklaşık değerdir.'),
  ('1.000.000 lira, aylık yüzde 2,5 faizle 120 ay eşit taksitli çekilirse aylık taksit yaklaşık 26.362 lira olur. Toplam geri ödeme anaparanın yaklaşık kaç katıdır?', '3,2 katı', ['1,3 katı', '2,0 katı', '4,5 katından fazla'], '26.362 × 120 ≈ 3.163.415 liradır; bu anaparanın yaklaşık 3,16 katıdır. Uzun vade ve yüksek faiz, toplam maliyeti çok büyütür.'),
  ('500.000 liralık, aylık yüzde 2 faizli, 60 ay vadeli eşit taksitli kredinin ilk 12 taksiti ödenmiştir; taksit yaklaşık 14.384 liradır. Bu noktada anaparanın kaçta kaçı ödenmiş olur?', 'Yaklaşık yüzde 12', ['Yaklaşık yüzde 20', 'Yaklaşık yüzde 50 civarı', 'Yaklaşık yüzde 35'], 'İlk yıl taksit ağırlıklı olarak faize gider; kalan borç yaklaşık 441.200 liradır. Anaparanın yaklaşık yüzde 11,8\'i ödenmiştir; yüzde 20 doğrusal ilerleme varsayımıdır.'),
  ('Kalan borcu 400.000 lira olan biri, aylık yüzde 3 yerine yüzde 2,5 faizli yeni bir krediyle borcunu kapatmayı düşünüyor ve yeni kredi için toplam 12.000 lira masraf ödeyecek. Aylık faiz tasarrufuna göre masrafın geri dönüş süresi kaç aydır?', '6 ay', ['3 ay', '12 ay', '24 ay'], 'Aylık faiz farkı 400.000 × 0,005 = 2.000 liradır. Masraf 12.000 lira olduğundan 12.000 ÷ 2.000 = 6 ayda geri döner.'),
  ('100.000 liralık krediye aylık yüzde 3 faiz uygulanıyor ve ilk üç ay ödemesiz dönem veriliyor, bu sürede faiz anaparaya ekleniyor. Üç ayın sonunda borç yaklaşık kaç liradır?', '109.273 lira', ['100.000 lira', '109.000,00 lira', '103.000 lira'], '100.000 × 1,03³ ≈ 109.273 liradır. Ödemesiz dönem faizsiz demek değildir; borç büyüyerek taksitlere yansır.'),
  ('600.000 liralık taşıt kredisinde aylık yüzde 2,2 faizle 36 ay vade seçilirse taksit yaklaşık 24.302 lira olur. Aracın peşinatı 200.000 lira ise kredi dahil araca ödenen toplam tutar yaklaşık ne kadardır?', '1.074.886 lira', ['800.000 lira', '874.886 lira', '1.200.000,00 lira'], 'Taksitler toplamı 24.302 × 36 ≈ 874.886 liradır. Peşinat eklenirse toplam 1.074.886 liraya ulaşır; araç etiketi 800.000 liradır.'),
  ('Aynı kredi tutarı ve vade için bir banka aylık yüzde 2,49, diğeri yüzde 2,59 faiz teklif ediyor. 200.000 liralık 24 aylık kredide iki teklifin toplam geri ödeme farkı yaklaşık ne kadardır?', 'Yaklaşık 2.972 lira', ['Yaklaşık 200 lira', 'Yaklaşık 20.000 lira', 'Yaklaşık 100 lira'], 'Taksitler yaklaşık 11.170 ve 11.294 liradır; aylık fark 124 lira, toplam fark 124 × 24 ≈ 2.972 liradır. Küçük görünen oran farkı büyük bir toplam fark yaratır.'),
  ('10.000 liralık anapara yıllık yüzde 36 basit faizle 92 gün tutuluyor. Yıl 365 gün alınırsa faiz yaklaşık kaç liradır?', '907 lira', ['920 lira', '900 lira', '990,50 lira'], 'Faiz = 10.000 × 0,36 × 92 ÷ 365 ≈ 907 liradır. Yıl 360 gün alınsaydı 920 lira çıkardı.'),
  ('Bankaların bazı uygulamalarında 360 günlük yıl kullanması mevduat sahibi ve borçlu için hangi sonucu doğurabilir?', 'Günlük faiz biraz yükselir', ['Günlük faiz düşer ve her iki taraf da kazanır', 'Faiz hesaplaması tamamen kalkar', 'Anapara iki kat büyür'], 'Yıl 360 alındığında günlük oran 1/360 olur ve 365\'e göre biraz yüksektir; bu fark küçüktür ama büyük anaparalarda belirgin hale gelir.'),
  ('Aylık yüzde 2,5 bileşik faizin yıllık efektif karşılığı yaklaşık yüzde kaçtır?', 'Yaklaşık yüzde 34,5', ['Yaklaşık yüzde 30,00', 'Yaklaşık yüzde 25,0', 'Yaklaşık yüzde 40,0'], '1,025¹² ≈ 1,345 olduğundan yıllık efektif oran yaklaşık yüzde 34,5\'tir; 12 × 2,5 = yüzde 30 basit toplama yanıltıcıdır.'),
  ('Aylık yüzde 1,5 faizin yıllıklaştırılmış basit ve bileşik karşılıkları hangisinde doğru verilmiştir?', 'Basit yüzde 18; bileşik yüzde 19,6', ['Basit yüzde 15; bileşik yaklaşık yüzde 16,0', 'Basit yüzde 18; bileşik yüzde 18', 'Basit yüzde 19,6; bileşik yüzde 18'], '1,5 × 12 = yüzde 18 basit orandır. Bileşik 1,015¹² − 1 ≈ yüzde 19,56\'dır.'),
  ('Günlük yüzde 0,1 faiz her gün anaparaya eklenerek 365 gün işlerse efektif yıllık getiri, basit yıllık yüzde 36,5 ile kıyaslandığında nasıldır?', 'Biraz yüksek; yaklaşık yüzde 44,03', ['Biraz düşüktür; yaklaşık yüzde 30,0', 'Aynıdır; yüzde 36,5', 'Çok yüksektir; yüzde 100'], '1,001³⁶⁵ ≈ 1,4405 olduğundan efektif yıllık getiri yaklaşık yüzde 44,03\'tir; basit toplama (yüzde 36,5) bileşik etkiyi yok sayar.'),
  ('Iyengar ve Lepper\'in reçel deneyinde 24 çeşit sunulan tezgâhla 6 çeşit sunulan tezgâh karşılaştırıldığında satın alma oranı nasıl çıkmıştır?', '24 çeşitte ilgi artmış ama satın alma düşük kalmıştır', ['24 çeşitli tezgâhta hem ilgi hem satın alma çok yüksek olmuştur', 'İki tezgâhta da hiç satış olmamıştır', '6 çeşitli tezgâhta ilgi ve satış çok düşük kalmıştır'], 'Seçenek bolluğu kararı zorlaştırır; 24 çeşitte ilgi artsa da satın alma oranı 6 çeşitteki orandan çok daha düşük kalmıştır.'),
  ('Her ay 5.000 lira katkıyla 20 yıl boyunca aylık yüzde 1 bileşik getiri elde eden bir emeklilik hesabında toplam birikim yaklaşık kaç liraya ulaşır?', 'Yaklaşık 4,95 milyon lira', ['Yaklaşık 1,20 milyon lira', 'Yaklaşık 2,40 milyon lira', 'Yaklaşık 12 milyon liradan fazla'], 'Düzenli ödemelerin gelecek değeri 5.000 × [(1,01²⁴⁰ − 1) ÷ 0,01] ≈ 4,95 milyon liradır. Katkılar toplamı yalnızca 1,2 milyon liradır; fark bileşik getiridir.'),
  ('Bugün aylık 40.000 lira harcama yapan biri, yıllık yüzde 15 enflasyonda 25 yıl sonra aynı yaşam standardı için aylık yaklaşık ne kadara ihtiyaç duyar?', 'Yaklaşık 1,3 milyon lira', ['Yaklaşık 40.000 lira', 'Yaklaşık 300.000 lira', 'Yaklaşık 5 milyon lira civarı'], '40.000 × 1,15²⁵ ≈ 1.316.758 liradır. Enflasyon uzun vadede aynı yaşam standardının maliyetini çok büyütür.'),
  ('Bir hanenin harcama sepeti: kira yüzde 40 (yıllık artış yüzde 60), gıda yüzde 35 (artış yüzde 80), ulaşım yüzde 25 (artış yüzde 40). Hanenin kişisel enflasyonu kaçtır?', 'Yüzde 62', ['Yüzde 60,5', 'Yüzde 54', 'Yüzde 70'], 'Ağırlıklı ortalama 0,40 × 60 + 0,35 × 80 + 0,25 × 40 = 24 + 28 + 10 = yüzde 62\'dir. Basit ortalama (60) ağırlıkları yok sayar.'),
  ('Yıllık yüzde 40 nominal faizli bir kredi çeken kişi, yıl sonunda enflasyonun yüzde 50 olduğunu görüyor. Yaklaşık reel faiz maliyeti nedir?', 'Yaklaşık yüzde −6,7', ['Yaklaşık yüzde +10,0', 'Yaklaşık yüzde −10', 'Yaklaşık yüzde +6,7'], '(1,40 ÷ 1,50) − 1 ≈ −yüzde 6,7\'dir; borç reel olarak azalmıştır. Ancak bu sonuç beklenmeyen enflasyondan doğar ve garantili değildir.'),
  ('Evli bir çift ortak giderler için ortak hesap açıp bu hesaba gelirleriyle orantılı tutar yatırıyor; birinin geliri 60.000, diğerinin 40.000 lira ve ortak gider 25.000 lira ise orantılı katkı paylaşımı kaçar liradır?', '15.000 ve 10.000 lira', ['12.500 lira ve 12.500 lira', '10.000 ve 15.000 lira', '20.000 ve 5.000 lira'], 'Gelir oranları 60:40 olduğundan ortak gider 3:2 bölünür: 25.000 × 0,6 = 15.000, 25.000 × 0,4 = 10.000 lira.'),
  ('Yüzde 30 indirimle 840 liraya satılan bir ürünün indirim öncesi fiyatı kaç liradır?', '1.200 lira', ['1.092 lira', '1.100 lira', '1.250,00 lira'], 'İndirimli fiyat liste fiyatının yüzde 70\'idir: 840 ÷ 0,70 = 1.200 liradır. 840 × 1,30 = 1.092 hatalı bir hesaptır.'),
  ('Aylık harcaması her ay yüzde 5 artan bir hanenin yıl sonundaki harcaması yılbaşına göre yaklaşık yüzde kaç artmış olur?', 'Yaklaşık yüzde 80', ['Yaklaşık yüzde 60', 'Yaklaşık yüzde 50', 'Yaklaşık yüzde 100'], '1,05¹² ≈ 1,796 olduğundan toplam artış yaklaşık yüzde 80\'dir; 12 × 5 = yüzde 60 basit toplamadır.'),
  ('Yıllık enflasyon yüzde 60 ise ortalama aylık bileşik enflasyon yaklaşık yüzde kaçtır?', 'Yaklaşık yüzde 4', ['Yaklaşık yüzde 5', 'Yaklaşık yüzde 6,5', 'Yaklaşık yüzde 2'], '1,60^(1/12) ≈ 1,0399 olduğundan aylık bileşik enflasyon yaklaşık yüzde 4\'tür; 60 ÷ 12 = yüzde 5 basit bölme ise abartılı bir sonuç verir.'),
  ('Yıllık yüzde 10 değer kaybeden bir cihazın dört yıl sonundaki değeri başlangıca göre yaklaşık yüzde kaç azalmıştır?', 'Yaklaşık yüzde 34', ['Yaklaşık yüzde 40', 'Yaklaşık yüzde 30,5', 'Yaklaşık yüzde 25'], '0,9⁴ ≈ 0,656 olduğundan değer yaklaşık yüzde 34 azalır; 4 × 10 = yüzde 40 doğrusal toplama hatasıdır.'),
  ('Bir esnaf 1.000 liraya aldığı ürünü yüzde 20 kârla satıyor. Satış fiyatı ve satış fiyatına göre kâr marjı hangisidir?', '1.200 lira; %16,7', ['1.200 lira; yüzde 20', '1.020 lira; yüzde 2', '1.250 lira; yüzde 25'], 'Satış fiyatı 1.200 liradır, kâr 200 liradır. Satış fiyatına göre marj 200 ÷ 1.200 ≈ yüzde 16,7\'dir; maliyete göre kâr yüzde 20\'dir.'),
  ('10 vat ve 20.000 saat ömürlü LED ampulün fiyatı 150 lira; 60 vat ve 1.000 saat ömürlü akkor ampulün fiyatı 15 liradır. Elektriğin kilovat saati 4 lira ise 20.000 saatlik kullanımda toplam maliyetler hangisidir?', 'LED 950 lira; akkor 5.100 lira', ['LED 150 lira; akkor 300 lira', 'LED 800 lira; akkor 4.800 lira', 'LED 2.000 lira; akkor 1.500 lira'], 'LED için 150 + 20.000 × 0,01 × 4 = 950 lira. Akkor için 20 ampul × 15 = 300 ve 20.000 × 0,06 × 4 = 4.800 lira; toplam 5.100 liradır.'),
  ('10.000 liralık bir cihaz 5 yıl, 6.000 liralık benzeri 2 yıl dayanıyor. Başka maliyet olmadan yıllık eşdeğer maliyet açısından hangisi daha ucuzdur?', '10.000 liralık; yılda 2.000 lira', ['6.000 liralık cihaz; yılda 2.000 lira', '6.000 liralık cihaz; yılda 3.000 lira', 'İkisi de yılda 3.000 lira'], 'İlk cihaz 10.000 ÷ 5 = 2.000 lira/yıl; ikincisi 6.000 ÷ 2 = 3.000 lira/yıl. Ucuz görünen ürün uzun vadede pahalı olabilir.'),
  ('800 liralık ayakkabı 6 ay, 2.000 liralık ayakkabı 24 ay dayanıyorsa aylık maliyetleri ve karşılaştırma hangisinde doğrudur?', '133 ve 83 lira/ay; pahalı olan ucuza gelir', ['800 liralık 83 lira/ay; 2.000 liralık 133 lira/ay', 'İkisi de 100 lira/ay', '800 liralık 400 lira/ay; 2.000 liralık 200 lira/ay'], '800 ÷ 6 ≈ 133 lira, 2.000 ÷ 24 ≈ 83 liradır. Dayanıklı ürünün kullanım başına maliyeti daha düşüktür.'),
  ('Her ay sonunda 3.000 lira yatıran ve hesabı aylık yüzde 1 bileşik getiri sağlayan kişi 50.000 liralık hedefe en az kaç ayda ulaşır?', '16 ay', ['12 ay', '17 ay', '20 ay kadar'], 'Gelecek değer formülünden n = ln(1 + 50.000 × 0,01 ÷ 3.000) ÷ ln(1,01) ≈ 15,5 çıkar; tam ay sayısı için 16 ay gerekir. Faizsiz hesapla 17 ay gerekirdi.'),
  ('100.000 liralık, aylık yüzde 2 faizli, 12 ay vadeli eşit taksitli kredinin taksidi yaklaşık 9.456 liradır. 6 taksit ödendikten sonra kalan anapara yaklaşık ne kadardır?', 'Yaklaşık 52.967 lira', ['Yaklaşık 50.000,00 lira', 'Yaklaşık 56.736 lira', 'Yaklaşık 43.264 lira'], 'Altı taksit sonunda kalan borç, 100.000 × 1,02⁶ − 9.456 × [(1,02⁶ − 1) ÷ 0,02] ≈ 52.967 liradır. Yarıdan biraz fazla borç kalır çünkü ilk taksitlerde faiz ağır basar.'),
  ('100.000 liralık, aylık yüzde 2 faizli, 12 ay vadeli kredi için bankanın yüzde 1 dosya masrafı (1.000 lira) kestiği ve borçlunun eline 99.000 lira geçtiği durumda gerçek aylık maliyet yaklaşık yüzde kaçtır?', 'Yaklaşık yüzde 2,16', ['Yaklaşık yüzde 2,00', 'Yaklaşık yüzde 1,00 civarı', 'Yaklaşık yüzde 3,00'], 'Taksitler 9.456 lira kalırken eline geçen tutar 99.000 liradır; bunu sağlayan aylık oran yaklaşık yüzde 2,16\'dır. Masraf, faiz oranını yüzde 2\'nin üzerine çıkarır.'),
  ('Taksit/gelir oranının en çok yüzde 35 olmasını isteyen bir kişi, 14.000 liralık aylık taksidi ödeyebilmek için en az ne kadar aylık net gelire sahip olmalıdır?', '40.000 lira', ['4.900,00 lira', '35.000 lira', '49.000 lira'], 'Gelir ≥ taksit ÷ oran = 14.000 ÷ 0,35 = 40.000 liradır.'),
  ('Yıl sonunda 1.000.000 lira biriktirmek isteyen biri 10 yıl boyunca her yıl sonunda yatıracaksa ve yıllık yüzde 20 getiri bekliyorsa yıllık katkısı yaklaşık ne olmalıdır?', 'Yaklaşık 38.523 lira', ['Yaklaşık 100.000 lira', 'Yaklaşık 83.333 lira', 'Yaklaşık 20.000 lira'], 'Katkı = 1.000.000 × 0,20 ÷ (1,20¹⁰ − 1) ≈ 38.523 liradır. Faizsiz hesapla 100.000 lira gerekirdi.'),
  ('Ay başında ödenen 10.000 liralık kira, aylık yüzde 1 iskonto oranında 12 ay boyunca bugünkü değer olarak (ay başı anüitesi) ay sonunda ödenen aynı kiradan nasıl farklıdır?', 'Ay başı daha değerli; 113.676 lira, ay sonu 112.551', ['İkisi tamamen aynıdır', 'Ay başı ödeme daha düşük değerlidir; yaklaşık 108.000 lira', 'Ay başı ödeme sıfır değerlidir'], 'Her ödeme bir dönem erken yapıldığından anüite değeri (1 + r) katına çıkar: 112.551 × 1,01 ≈ 113.676 liradır.'),
  ('Ay başlarında 2.000 lira yatıran ve aylık yüzde 1 bileşik getiri elde eden kişinin 12. ay sonunda birikimi ay sonu yatırımına göre nasıl olur?', 'Daha yüksek; 25.619 lira', ['Daha düşük olur; yaklaşık 24.000 lira', 'Aynı olur; 24.000 lira', 'Daha düşük olur; yaklaşık 20.000 lira'], 'Ay başı yatırımlar bir ay daha faiz kazanır: 25.365 × 1,01 ≈ 25.619 liradır.'),
  ('Birinci hafta 1 lira, ikinci hafta 2 lira, ... elli ikinci hafta 52 lira biriktirilen "52 hafta tasarruf meydan okuması"nda yıl sonunda toplam birikim kaç liradır?', '1.378 lira', ['1.352 lira', '2.704,00 lira', '1.326 lira'], '1\'den 52\'ye kadar sayıların toplamı 52 × 53 ÷ 2 = 1.378\'dir. Küçük ve artan tutarlar yıl boyu disiplin kazandırır.'),
  ('Bir su idaresinde ilk 10 metreküpün her biri 20 lira, sonraki her metreküp 40 lira ise 18 metreküp tüketimin faturası kaç liradır?', '520 lira', ['360 lira', '720,00 lira', '400 lira'], 'İlk 10 m³ için 10 × 20 = 200, kalan 8 m³ için 8 × 40 = 320 lira ödenir; toplam 520 liradır. Kademeli tarife fazla tüketimi caydırır.'),
  ('Gelirini artırmak isteyen bir çalışanın bütçe sorununa uzun vadeli çözüm olarak hangi yaklaşım daha kalıcıdır?', 'Yeni beceri edinmek', ['Daha fazla borç alıp harcamayı artırmak', 'Birikimi tamamen bitirmek', 'Faiz oranının düşmesini beklemek'], 'Beceri geliştirmek gelir artışını sürdürülebilir kılar; borçlanma gelir sorununu çözmez, yalnızca erteler.'),
  ('100.000 liralık 24 aylık eşit taksitli kredi için A bankası aylık yüzde 2 faizle masrafsız, B bankası aylık yüzde 1,8 faizle ve yüzde 2 dosya masrafıyla teklif veriyor (masraf kredi tutarından düşülüyor, eline 98.000 lira geçiyor). Gerçek aylık maliyete göre hangisi daha ucuzdur?', 'B bankası; gerçek maliyet yaklaşık yüzde 1,98', ['A bankası; çünkü B\'nin masrafı faiz avantajını tamamen yok eder', 'İkisi tamamen aynıdır', 'B bankası; çünkü gerçek maliyeti yüzde 1,8\'dir'], 'B\'nin taksidi yaklaşık 5.168 liradır; 98.000 lira net tutara karşılık bunu veren aylık oran yaklaşık yüzde 1,977\'dir. Bu A\'nın yüzde 2\'sinden küçüktür; fark küçük olsa da B ucuzdur.'),
  ('Her ay 10.000 lira sabit taksit ödeyen bir borçlunun, aylık yüzde 4 enflasyonda, 12. taksitinin ilk aya göre alım gücü yaklaşık kaç liraya denk gelir?', 'Yaklaşık 6.496 lira', ['Yaklaşık 10.000 lira', 'Yaklaşık 5.000 lira', 'Yaklaşık 8.333 lira'], '11 ay sonraki fiyat düzeyi 1,04¹¹ ≈ 1,539 katıdır; 10.000 ÷ 1,539 ≈ 6.496 liradır. Sabit taksitler enflasyonda reel olarak erir.'),
  ('A bankası 6 ay vadeli yıllık yüzde 40 basit faiz veriyor ve vade sonunda faiz ile anapara aynı faizle yeniden 6 ay yatırılıyor; B bankası 12 ay vadeli yüzde 36 faiz veriyor. Bir yılın sonunda hangisi daha yüksek getiri sağlar?', 'A; yüzde 44, B\'de yüzde 36', ['B; yıllık efektif getiri yüzde 40', 'İkisi aynı getiriyi sağlar', 'A; yıllık efektif getiri yüzde 40'], 'A\'da 6 ayda yüzde 20 getiri, yenilenince 1,2 × 1,2 = 1,44 olur; yıllık getiri yüzde 44\'tür. B yüzde 36 verir.'),
  ('Ekstre borcu 10.000 lira olan bir kart sahibi her ay kalan borcun yüzde 20\'sini asgari ödeme olarak yatırıyor, kalan bakiyeye aylık yüzde 4 faiz işleniyor ve yeni harcama yapmıyor. İkinci ayın sonunda borcu yaklaşık kaç lira olur?', 'Yaklaşık 6.922 lira', ['Yaklaşık 6.000,00 lira', 'Yaklaşık 6.400 lira', 'Yaklaşık 8.000 lira'], '1. ay: (10.000 − 2.000) × 1,04 = 8.320. 2. ay: (8.320 − 1.664) × 1,04 ≈ 6.922 liradır. Asgari ödeme borcu çok yavaş eritir.'),
  ('100.000 lirasını 6 yıl içinde 200.000 liraya çıkarmak isteyen kişinin gereken yıllık bileşik getiri yaklaşık yüzde kaçtır?', 'Yaklaşık yüzde 12,2', ['Yaklaşık yüzde 16,7', 'Yaklaşık yüzde 10,00', 'Yaklaşık yüzde 8,3'], '2^(1/6) − 1 ≈ 0,1225\'tir. Basit bölme (yüzde 100 ÷ 6 ≈ 16,7) bileşik etkiyi yok sayar.'),
  ('3 yıl boyunca maaş zamları sırasıyla yüzde 30, 25 ve 20, yıllık enflasyon ise yüzde 40, 35 ve 30 olan bir çalışanın üç yıllık reel maaş değişimi yaklaşık nedir?', 'Yüzde 20,6 azalma', ['Yaklaşık yüzde 10 azalma', 'Yaklaşık yüzde 20,6 artış', 'Reel değişim yoktur'], 'Maaş 1,30 × 1,25 × 1,20 = 1,95 katına, fiyatlar 1,40 × 1,35 × 1,30 ≈ 2,457 katına çıkar. 1,95 ÷ 2,457 ≈ 0,794; reel maaş yaklaşık yüzde 20,6 düşer.'),
  ('50.000 lira mevduatı yıllık yüzde 35 net getirili olan, ayrıca yıllık yüzde 60 faizli kredi kartı borcu bulunan biri mevduatı borcu kapatmaya yönlendirirse yıllık yaklaşık net kazancı kaç liradır?', 'Yaklaşık 12.500 lira', ['Yaklaşık 17.500 lira', 'Yaklaşık 30.000,00 lira', 'Yaklaşık 0 lira'], 'Borcun maliyeti 50.000 × 0,60 = 30.000, mevduat getirisi 17.500 liradır. Kapatmanın net kazancı 30.000 − 17.500 = 12.500 liradır.'),
  ('5.000.000 liralık emeklilik birikimini ilk yıl yüzde 4 çekim kuralıyla kullanacak biri yıllık ne kadar çeker ve bu aylık yaklaşık kaç liraya denk gelir?', 'Yılda 200.000; ayda yaklaşık 16.667 lira', ['Yılda 400.000 lira; ayda yaklaşık 33.333 lira', 'Yılda 20.000 lira; ayda yaklaşık 1.667 lira', 'Yılda 125.000 lira; ayda yaklaşık 10.417 lira'], '5.000.000 × 0,04 = 200.000 liradır; 12 aya bölünce ayda yaklaşık 16.667 lira çıkar.'),
  ('Katılma hesabında fonun getirisi yüzde 50, hesap sahibinin kâr payı oranı yüzde 60 ise hesap sahibine yansıyan getiri yüzde kaçtır?', 'Yüzde 30', ['Yüzde 50', 'Yüzde 60', 'Yüzde 10\'a yakın'], 'Hesap sahibi fon getirisinin yüzde 60\'ını alır: 50 × 0,60 = yüzde 30\'dur.'),
  ('Aylık net geliri 40.000, gideri 45.000 lira olan bir kişi giderlerini yüzde 10 azaltırsa bütçe dengesi nasıl olur?', 'Gider 40.500 lira olur; hâlâ 500 lira açık verir', ['Gider 36.000 lira olur; 4.000 lira fazla verir', 'Gider 40.500 lira; aylık 500 lira fazla', 'Gider değişmez; açık 5.000 lira kalır'], '45.000 × 0,90 = 40.500 liradır; gelir 40.000 lira olduğundan 500 liralık açık hâlâ sürer. Bu nedenle ek tasarruf ya da ek gelir gerekir.'),
  ('20.000 lira aylık kirası olan evin kirası iki yıl üst üste yüzde 45 artarsa ikinci yılın sonunda aylık kira kaç lira olur?', '42.050 lira', ['38.000,00 lira', '29.000 lira', '40.000 lira'], '20.000 × 1,45² = 42.050 liradır; iki yıllık artış yüzde 110,25\'tir, yüzde 90 değil.'),
  ('İki yıl boyunca her yıl başında 20.000 lira yatıran ve yıllık yüzde 25 bileşik getiri sağlayan kişinin 2. yılın sonundaki birikimi kaç liradır?', '56.250 lira', ['50.000 lira', '45.000 lira', '62.500,00 lira'], 'İlk yatırım iki yıl işler: 20.000 × 1,25² = 31.250. İkinci yatırım bir yıl işler: 20.000 × 1,25 = 25.000. Toplam 56.250 liradır.'),
  ('Yıl sonlarında 28.800 lira (aylık 2.400 lira karşılığı) biriktirip hesabına yatıran ve yıllık yüzde 15 bileşik getiri elde eden biri 3 yılın sonunda yaklaşık ne kadar biriktirir?', 'Yaklaşık 100.000 lira', ['Yaklaşık 86.400 lira', 'Yaklaşık 115.200,00 lira', 'Yaklaşık 250.000 lira'], 'Yıllık katkı 28.800 lira, yıl sonu ödemesiyle üç yıllık gelecek değeri 28.800 × [(1,15³ − 1) ÷ 0,15] ≈ 100.008 liradır; düz toplam 86.400 liradır.'),
  ('Eşit anapara ödemeli kredinin ilk taksidi 12.400 lira, son taksidi 10.200 lira ise taksitlerin ortalaması ve bunun anlamı nedir?', 'Ortalama yaklaşık 11.300; doğrusal azalır', ['Ortalama 12.400 lira; taksitler artar', 'Ortalama 10.200 lira; taksitler sabittir', 'Ortalama 22.600 lira; taksitler iki katına çıkar'], 'Faiz doğrusal azaldığından taksitler de doğrusal azalır; ortalama (12.400 + 10.200) ÷ 2 = 11.300 liradır.'),
  ('Bir kişi yüzde 36 yıllık enflasyonda yıllık yüzde 30 net faiz getirisi sağlayan mevduata 200.000 lira yatırıyor. Yıl sonunda hesabındaki paranın bugünkü alım gücüyle ifadesi yaklaşık kaç liradır?', 'Yaklaşık 191.176 lira', ['Yaklaşık 260.000 lira', 'Yaklaşık 200.000 lira', 'Yaklaşık 170.000,00 lira'], 'Yıl sonunda hesap 260.000 liradır; fiyatlar 1,36 katına çıktığından bugünkü değeri 260.000 ÷ 1,36 ≈ 191.176 liradır. Reel kayıp yaklaşık yüzde 4,4\'tür.'),
  ('Taksit/gelir oranı yüzde 30 olan bir kişinin geliri yüzde 20 artarken taksiti aynı kalırsa yeni oran yaklaşık yüzde kaç olur?', 'Yaklaşık yüzde 25', ['Yaklaşık yüzde 24', 'Yaklaşık yüzde 30', 'Yaklaşık yüzde 36,0'], 'Gelir 1,20 katına çıktığında oran 30 ÷ 1,20 = yüzde 25 olur; yüzde 24 yalnızca puan çıkarmayla bulunan hatalı sonuçtur.'),
  ('5 yıl boyunca her ay sonunda 3.000 lira yatıran ve hesabı aylık yüzde 1 bileşik getiri sağlayan kişi, 5 yıl sonra yatırmayı bırakıp parayı 5 yıl daha aynı getiriyle bekletirse 10. yılın sonunda hesabı yaklaşık kaç lira olur?', 'Yaklaşık 445.000 lira', ['Yaklaşık 245.000,00 lira', 'Yaklaşık 360.000 lira', 'Yaklaşık 180.000 lira'], '5 yıl sonunda birikim 3.000 × [(1,01⁶⁰ − 1) ÷ 0,01] ≈ 245.009 liradır. Bu tutar 5 yıl daha 1,01⁶⁰ ≈ 1,817 katına büyür: yaklaşık 445.107 lira.'),
  ('Aylık 15.000 lira kira ödeyen bir kiracının kirası her yıl yüzde 30 artıyor. Aynı konut için sabit taksitli bir kredinin aylık taksidi 25.000 liradır. Kira kaçıncı yıl taksiti aşar (ilk yıl 15.000 lira)?', 'Üçüncü yılda', ['İkinci yılda', 'Dördüncü yılda', 'Hiçbir zaman aşmaz'], 'Kira 1. yıl 15.000, 2. yıl 19.500, 3. yıl 25.350 liradır. Üçüncü yılda 25.000 liralık taksidi geçer.'),
  ('Bugün 100.000 lira ile 3 yıl sonra 150.000 lira arasında seçim yapan bir kişi parasını yıllık yüzde 15 getiriyle değerlendirebiliyorsa hangisini seçmelidir?', 'Bugünkü 100.000 lirayı; 150.000\'in bugünkü değeri 98.627 lira', ['3 yıl sonraki 150.000 lirayı; çünkü bugünkü değeri 130.000 liradır', 'İkisi tam olarak eşittir', '3 yıl sonraki 150.000 lirayı; çünkü bugünkü değeri 105.000 liradır'], '150.000 ÷ 1,15³ ≈ 98.627 lira eder; bu da 100.000 liradan küçüktür. Fark az olduğundan hassas bir karardır.'),
  ('60.000 lira kart borcuna aylık yüzde 3 faiz işleyen kişi her ay 3.000 lira ödüyor ve yeni harcama yapmıyor. Borcun tamamen kapanması yaklaşık kaç ay sürer?', 'Yaklaşık 31 ay', ['Yaklaşık 20 ay', 'Yaklaşık 15 ay', 'Yaklaşık 60 ay kadar'], 'n = −ln(1 − 60.000 × 0,03 ÷ 3.000) ÷ ln(1,03) ≈ 31 aydır. Faizsiz olsaydı 20 ay yeterdi; ilk ay ödemenin 1.800 lirası faize gider.'),
  ('100.000 liralık borca aylık yüzde 3 faiz işleyen kişi her ay yalnızca 2.500 lira ödüyorsa borcun gidişatı nasıl olur?', 'Borç büyür', ['Borç her ay 2.500 lira azalır', 'Borç değişmez', 'Borç ilk ayda tamamen kapanır'], 'Faiz 100.000 × 0,03 = 3.000 liradır; ödenen 2.500 lira faizin altında kaldığı için kalan 500 lira borca eklenir. Bu durum negatif amortisman denir.'),
  ('Yıllık yüzde 40 net getirisi olan hesapta 100.000 lira üç yıl bekliyor ve yıllık enflasyon her yıl yüzde 45 oluyor. Üç yıl sonunda hesabın bugünkü fiyatlarla satın alma gücü yaklaşık kaç liradır?', 'Yaklaşık 90.000 lira', ['Yaklaşık 274.400 lira', 'Yaklaşık 100.000 lira', 'Yaklaşık 60.000 lira'], 'Hesap 100.000 × 1,40³ = 274.400 liraya çıkar; fiyatlar 1,45³ ≈ 3,05 katı olur. Reel değer 274.400 ÷ 3,05 ≈ 90.000 liradır.'),
  ('100.000 liralık, aylık yüzde 2 faizli, 12 ay vadeli eşit taksitli kredide taksit yaklaşık 9.456 liradır. İkinci taksitin anapara payı yaklaşık kaç liradır?', 'Yaklaşık 7.605 lira', ['Yaklaşık 7.456,00 lira', 'Yaklaşık 2.000 lira', 'Yaklaşık 9.456 lira'], 'İlk taksitte faiz 2.000, anapara 7.456 liradır. Kalan 92.544 liranın faizi 1.851 liradır; ikinci taksitin anapara payı 9.456 − 1.851 ≈ 7.605 liradır.'),
  ('Hedef olarak belirlenen ev peşinatı bugün 300.000 liradır ve aylık yüzde 3 artıyor; biriktiren kişi ayda 5.000 lira ayırıyor (faiz yok). Bu plan hedefe ulaşır mı?', 'Hayır; hedef birikimden hızlı büyür', ['Evet; 60 ayda ulaşır', 'Evet; 30 ayda ulaşır', 'Hayır; hedef her ay 3.000 lira düşer'], 'Hedef ilk ay 300.000 × 0,03 = 9.000 lira artar; birikim ise yalnızca 5.000 liradır. Fark açıldığı için hedefe ulaşılamaz; getirili araç ya da daha yüksek katkı gerekir.'),
  ('Gelir vergisi yüzde 15, SGK ve işsizlik toplamı yüzde 15 (brüt üzerinden), damga vergisi binde 7,59 varsayımıyla (gelir vergisi SGK sonrası matrah üzerinden) net maaşı 36.000 lira olan bir kişinin brüt maaşı yaklaşık kaç liradır?', 'Yaklaşık 50.356 lira', ['Yaklaşık 41.400 lira', 'Yaklaşık 54.000 lira', 'Yaklaşık 45.000,00 lira'], 'Net = brüt × (1 − 0,15 − 0,15 × 0,85 − 0,00759) ≈ brüt × 0,7149 olduğundan brüt = 36.000 ÷ 0,7149 ≈ 50.356 liradır.'),
  ('İki ödeme planından biri 12 ay boyunca her ay sonunda 10.000 lira, diğeri bugün 105.000 liradır. Aylık yüzde 2 iskonto oranında hangisi tüketici için daha uygundur?', 'Bugün 105.000 lira; 12 aylık planın değeri 105.753', ['12 aylık plan; çünkü toplam 120.000 lira daha düşük etkiye sahiptir', 'İkisi eşittir', 'Bugün 105.000 lira ödemek; çünkü 12 aylık planın bugünkü değeri 120.000 liradır'], '10.000 × [(1 − 1,02⁻¹²) ÷ 0,02] ≈ 105.753 liradır. Peşin 105.000 lira bundan küçük olduğundan peşin ödeme biraz daha avantajlıdır.'),
  ('Yıllık yüzde 24 basit faizle 5 yıl bekleyen bir paranın toplam büyümesi 2,2 katıdır. Aynı toplam büyümeyi sağlayacak yıllık bileşik oran yaklaşık yüzde kaçtır?', 'Yaklaşık yüzde 17', ['Yaklaşık yüzde 24', 'Yaklaşık yüzde 20', 'Yaklaşık yüzde 12,5'], '2,2^(1/5) − 1 ≈ 0,171 olduğundan bileşik oran yaklaşık yüzde 17\'dir; bileşik faizde aynı sonuca daha düşük oranla ulaşılır.'),
  ('Aylık 60.000 lira geliri olan bir hanede aylık gider 54.000 lira olup hedef birikim oranı yüzde 15\'tir. Hedefe ulaşmak için gider yaklaşık ne kadar azaltılmalıdır?', 'Yaklaşık 3.000 lira', ['Yaklaşık 6.000 lira', 'Yaklaşık 9.000,00 lira', 'Yaklaşık 1.500 lira'], 'Hedef birikim 60.000 × 0,15 = 9.000 liradır. Mevcut birikim 6.000 lira olduğundan gider 3.000 lira azaltılmalıdır.'),
  ('Günde ortalama 100 lira küçük harcamayı (kahve, atıştırmalık) yılda 250 iş günü yapan biri bu harcamayı bırakıp tutarı yılsonlarında yıllık yüzde 20 bileşik getiriyle 20 yıl biriktirirse yaklaşık ne kadar toplanır?', 'Yaklaşık 4,67 milyon lira', ['Yaklaşık 500.000 lira', 'Yaklaşık 1,2 milyon lira civarı', 'Yaklaşık 25.000 lira'], 'Yıllık tutar 25.000 liradır; gelecek değeri 25.000 × [(1,20²⁰ − 1) ÷ 0,20] ≈ 4,67 milyon liradır. Küçük harcamalar zamanla büyük bir fırsat maliyeti yaratır.'),
  ('Hanenin toplam borcunun yıllık net gelirine oranına hanehalkı borçluluk oranı denir. Borcu 600.000, yıllık net geliri 480.000 lira olan hanenin oranı kaçtır?', 'Yüzde 125', ['Yüzde 80', 'Yüzde 125 değil, yüzde 25', 'Yüzde 12,5'], '600.000 ÷ 480.000 = 1,25 yani yüzde 125\'tir. Oran yüksekse gelir şoklarında ödeme sorunu riski büyür.'),
  ('Yaşı 35 olan, bakmakla yükümlü olduğu iki çocuğu bulunan ve yıllık net geliri 480.000 lira olan bir çalışan için sık anılan "gelirin 10 katı" kuralı hayat sigortası teminatı için yaklaşık ne kadar önerir?', 'Yaklaşık 4,8 milyon lira', ['Yaklaşık 480.000 lira', 'Yaklaşık 48.000 lira', 'Yaklaşık 48 milyon liradan fazla'], '480.000 × 10 = 4.800.000 liradır; bu pratik kural, gelirin birkaç yıl yerine konmasını hedefler. Gerçek ihtiyaç borç ve hedeflere göre ayarlanmalıdır.'),
];
